local ADDON_NAME = ...
OneWoW.CatalogData:Defer(ADDON_NAME, 'quest', function()
return {
[30134] = {id=30134,name="Wild Things",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="Welcome to the Order of the Cloud Serpent, . I can see from the spark in your eye that you wish to join the Order. Let me get a good look at you. Elder Anli gently holds your head and gazes at your face.> Hmm. I see honesty and earnestness in your heart. You have journeyed far to come here, but I am afraid you must go yet further. Your path into the Order begins now. Speak to Instructor Tong at Windward Isle to the northeast to take the first step.",starts={{npcID=58564,x=0.576,y=0.448,zoneID=5785}},ends={{npcID=58225,x=0.654,y=0.316,zoneID=5785}},coords={x=0.576,y=0.448,source="quest_giver",zoneID=5785},questType="world",worldTaskTitle="Wild Things"},
[31001] = {id=31001,name="Falling Down",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="It's bad enough trying to hold off the mantid, but now we've got spiders swarming up from the ruins below. One of my best marksmen caught a blast of webbing around his leg and got pulled straight down! We think he's alive, but I don't have the manpower to send anyone in after him. We're stretched thin up here, . If you want to help, use the rope behind me to drop down into the ruins. You're not afraid of heights are you? How about spiders?",starts={{npcID=62112,x=0.14,y=0.77,zoneID=5840}},ends={{npcID=62166,x=0.724,y=0.286,zoneID=6138}},coords={x=0.14,y=0.77,source="quest_giver",zoneID=5840},questType="world",worldTaskTitle="Falling Down"},
[31394] = {id=31394,name="A Celestial Experience",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,mapID=379,description="Nobody is allowed into the Vale without the approval of the August Celestials. Xuen , The White Tiger, appears ready to listen to me. But Taran Zhu of the Shado-Pan is reluctant to let the Alliance or Horde anywhere NEAR the Vale after all that's happened. Maybe you can help me make my case. Speak to the White Tiger on our behalf. Be careful! He may set a number of challenges before you...",starts={{npcID=64540,x=0.688,y=0.432,zoneID=5841}},ends={{npcID=64540,x=0.688,y=0.432,zoneID=5841}},coords={x=0.688,y=0.432,source="quest_giver",zoneID=5841},questType="world",worldTaskTitle="A Celestial Experience"},
[31395] = {id=31395,name="A Celestial Experience",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,mapID=379,description="The human calf is arguing on our behalf. He is well-spoken; I can see why Baine Bloodhoof regards the prince so highly. Still, the argument does not go well. I am of little consequence, but you are a hero of the Horde. Perhaps you can intercede in our favor? Speak with the White Tiger and plead our case, . Be careful! He may set a number of challenges before you...",starts={{npcID=64542,x=0.686,y=0.43,zoneID=5841}},ends={{npcID=64542,x=0.686,y=0.43,zoneID=5841}},coords={x=0.686,y=0.43,source="quest_giver",zoneID=5841},questType="world",worldTaskTitle="A Celestial Experience"},
[31511] = {id=31511,name="A Witness to History",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=9105,mapID=379,description="I will gather up the other Tauren pilgrims and we will travel into the Vale together. Meet me at the Gate of the August Celestials at the southern edge of Kun-Lai Summit and speak with me there.",starts={{npcID=64542,x=0.686,y=0.43,zoneID=5841}},ends={{npcID=62996,x=0.63,y=0.12,zoneID=9105}},coords={x=0.686,y=0.43,source="quest_giver",zoneID=5841},questType="world",worldTaskTitle="A Witness to History"},
[31512] = {id=31512,name="A Witness to History",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=9105,mapID=379,description="The celestials are allowing us back into the Vale! This will be a sight to behold. We shouldn't waste any time. Head to the Gate of the August Celestials at the southern edge of Kun-Lai Summit and speak with me there.",starts={{npcID=64540,x=0.688,y=0.432,zoneID=5841}},ends={{npcID=64149,x=0.872,y=0.668,zoneID=9105}},coords={x=0.688,y=0.432,source="quest_giver",zoneID=5841},questType="world",worldTaskTitle="A Witness to History"},
[32246] = {id=32246,name="Meet the Scout",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="It has been two months since the parting of the mists. Alliance scouts, seeking a suitable landing site for the fleet, have engaged Horde forces on a beach in Krasarang Wilds. Meet with Scout Lynna and help secure the landing site.",starts={{npcID=64610,x=0.84,y=0.588,zoneID=5840}},ends={{npcID=68311,x=0.852,y=0.29,zoneID=6134}},coords={x=0.84,y=0.588,source="quest_giver",zoneID=5840},questType="world",worldTaskTitle="Meet the Scout"},
[32249] = {id=32249,name="Meet the Scout",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,mapID=418,description="It has been two months since the parting of the mists. Horde scouts, seeking a suitable landing site for the fleet, have engaged Alliance forces on a small island off the coast of Krasarang Wilds. Meet with Scout Rokla and help secure the landing site.",starts={{npcID=64566,x=0.628,y=0.28,zoneID=5840}},ends={{npcID=67812,x=0.086,y=0.644,zoneID=6134}},coords={x=0.628,y=0.28,source="quest_giver",zoneID=5840},questType="world",worldTaskTitle="Meet the Scout"},
