[32497] = {id=32497,name="Honor the Flame",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6134,mapID=422,description="The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, ?",starts={{npcID=69522,x=0.561,y=0.695,zoneID=6138}},ends={{npcID=217845,x=0.561,y=0.696,zoneID=6138},{npcID=217845,x=0.472,y=0.472,zoneID=5785},{npcID=217845,x=0.519,y=0.514,zoneID=5805},{npcID=217845,x=0.711,y=0.909,zoneID=5841},{npcID=217845,x=0.715,y=0.563,zoneID=5842},{npcID=217845,x=0.74,y=0.095,zoneID=6134}},coords={x=0.561,y=0.695,source="quest_giver",zoneID=6138},questType="world",worldTaskTitle="Honor the Flame"},
