[32680] = {id=32680,name="The Storm Gathers",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="There is no time to waste, . Every moment we delay here gives Jaina and the Kirin Tor more of a hold on the Isle. Lor'themar awaits us. Speak to me when you are ready to depart. I will escort you there myself.",starts={{npcID=70358,x=0.508,y=0.732,mapID=388}},ends={{npcID=67990,x=0.326,y=0.354,mapID=504}},coords={x=0.508,y=0.732,source="quest_giver",mapID=504},questType="world",worldTaskTitle="The Storm Gathers"},
[32681] = {id=32681,name="The Storm Gathers",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=505,description="There is no time to waste, . Every moment we delay here gives the Sunreavers more of a hold on the Isle. Lady Jaina Proudmoore awaits us. We should not make her wait any longer. Speak to me when you are ready to depart. I will escort you there myself.",starts={{npcID=70360,x=0.498,y=0.69,zoneID=5842}},ends={{npcID=67992,x=0.632,y=0.722,zoneID=6507}},coords={x=0.498,y=0.69,source="quest_giver",zoneID=5842},questType="world",worldTaskTitle="The Storm Gathers"},
