[57718] = {id=57718,name="Bound in Stone",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="Some of our warriors were camped in the small settlement near Guo-Lai when the Baruk invaded the area. Some managed to escape, but they returned with tales of their brothers and sisters in arms being petrified by the mogu stoneshapers into living statues! We can't leave our warriors behind! The stoneshapers must carry some means to reverse the spell and free them from their stone prisons. Bring our soldiers back!",starts={{npcID=158673,x=0.384,y=0.752,zoneID=9105}},ends={{npcID=158673,x=0.384,y=0.752,zoneID=9105}},coords={x=0.384,y=0.752,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Bound in Stone"},
[57720] = {id=57720,name="Champions of the Mogu",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="These lesser clans warring with each other in the Vale need to be taught their place. Seek out their champions and eliminate them. Show them that only the Rajani have rightful claim here!",starts={{npcID=154444,x=0.446,y=0.74,zoneID=9105}},ends={{npcID=154444,x=0.446,y=0.74,zoneID=9105}},coords={x=0.446,y=0.74,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Champions of the Mogu"},
[57721] = {id=57721,name="Spoils of War",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="The warring clans are relentless and our warriors are going through armor faster than I can keep it repaired. If you find yourself in battle with the other clans, see if you can salvage any undamaged armor pieces from their soldiers. We should not let good resources go to waste.",starts={{npcID=154677,x=0.438,y=0.718,zoneID=9105}},ends={{npcID=154677,x=0.438,y=0.718,zoneID=9105}},coords={x=0.438,y=0.718,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Spoils of War"},
[57728] = {id=57728,name="Assault: The Endless Swarm",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=5841,mapID=1530,description="The mantid swarm is surging! There's no way the Golden Lotus will be able to handle this many of them. We must do something to drive them back!",ends={{npcID=161405,x=0.372,y=0.792,zoneID=9105}},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Cull the mantid swarm"}},worldTaskTitle="Assault: The Endless Swarm",db2QuestInfoID=268,db2QuestInfoName="Threat Wrapper"},
