[58420] = {id=58420,name="A Foul Annoyance",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="The Hozen are opportunistic and weak. It does not surprise me that some of their kind have thrown their lot in with the Old Gods. We should take care of them before they become more than a nuisance.",starts={{npcID=154444,x=0.446,y=0.74,zoneID=9105}},ends={{npcID=154444,x=0.446,y=0.74,zoneID=9105}},coords={x=0.446,y=0.74,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="A Foul Annoyance"},
[58422] = {id=58422,name="Mark of the Conquerors",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="The invading minions of N'Zoth lay claim to lands they are not entitled to. The Vale will not be conquered while even one of the Rajani still draws breath. Burn down their banners as a reminder of this.",starts={{npcID=154444,x=0.446,y=0.74,zoneID=9105}},ends={{npcID=154444,x=0.446,y=0.74,zoneID=9105}},coords={x=0.446,y=0.74,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Mark of the Conquerors"},
[58423] = {id=58423,name="The Strongest Among Them",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="You have shown great strength in your conquests, but new enemies assail the Vale with each day. Seek out the strongest that our foes have sent forth, and bring them down for their allies to see.",starts={{npcID=154444,x=0.446,y=0.74,zoneID=9105}},ends={{npcID=154444,x=0.446,y=0.74,zoneID=9105}},coords={x=0.446,y=0.74,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="The Strongest Among Them"},
