[58442] = {id=58442,name="Consuming Maw",level=50,requiredLevel=50,faction="none",expansion=4,zoneID=5840,mapID=390,questType="world",worldTaskTitle="Consuming Maw",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[58460] = {id=58460,name="Marshals of Madness",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="The n'raqi have long served as the commanders and taskmasters of the Old Gods' forces. Their presence on the field of battle shows that this invasion is a coordinated effort rather than a random outbreak of corruption. Led by these faceless masters, the chaotic forces of the Old Gods transform into capable military. We must make it a priority to fell these creatures. Only then might we take the upper hand against N'Zoth.",starts={{npcID=154444,x=0.446,y=0.74,zoneID=9105}},ends={{npcID=154444,x=0.446,y=0.74,zoneID=9105}},coords={x=0.446,y=0.74,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Marshals of Madness",db2QuestInfoID=1,db2QuestInfoName="Group"},
[58461] = {id=58461,name="Tomes of Ancient Madness",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="In times like these, it becomes necessary for all of the denizens of the Vale to pitch in and do their part. Unfortunately, I have never been much of a fighter, so my usefulness in times of war is limited. However, I may be able to do some good. You see, we know very little about the invaders we face, and knowledge can be a very powerful weapon. I think I have seen tomes carried by some of the k'thir. If you could bring some to me, I may be able to glean something useful from their writings.",starts={{npcID=156003,x=0.836,y=0.272,zoneID=9105}},ends={{npcID=156003,x=0.836,y=0.272,zoneID=9105}},coords={x=0.836,y=0.272,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Tomes of Ancient Madness"},
[58462] = {id=58462,name="Windows to the Soul",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="Were it not enough for our enemy to apply deadly force against us, their minions also strike into the very heart of our defenders. I speak, of course, of the eyes. They peer into the souls of our warriors and produce their darkest fears against them. If we have any hope to defeat this foe, they must be destroyed.",starts={{npcID=154261,x=0.838,y=0.49,zoneID=9105}},ends={{npcID=154261,x=0.838,y=0.49,zoneID=9105}},coords={x=0.838,y=0.49,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Windows to the Soul"},
[58463] = {id=58463,name="Spawns of Madness",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="To see the Vale of Eternal Blossoms recover from the Sha to its former beauty, only to see it tainted by the Old Gods once more, it makes the blood boil! We must root out the Old God's corruption before it can take hold of this land again. I have seen the fleshbeasts that accompany N'Zoth's forces spreading his corruption where they tread. Make sure they tread no longer.",starts={{npcID=161404,x=0.664,y=0.406,zoneID=9105}},ends={{npcID=161404,x=0.664,y=0.406,zoneID=9105}},coords={x=0.664,y=0.406,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Spawns of Madness"},
[58464] = {id=58464,name="Deephive Decimation",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="A sect of the mantid swarm calling themselves the \"Deephive\" have taken hold of the Big Blossom mine. These mantid have fully given themselves up to the Old Gods' corruption, making them especially dangerous. We cannot allow the Deephive to run amok in the Vale. Do what must be done.",starts={{npcID=161405,x=0.372,y=0.792,zoneID=9105}},ends={{npcID=161405,x=0.372,y=0.792,zoneID=9105}},coords={x=0.372,y=0.792,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Deephive Decimation"},
[58465] = {id=58465,name="Corruption Manifest",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="The corruption of the Old Gods is often so foul it manifests itself in physical form. We have seen this with the Sha. This time is no different. Cull this corruption wherever you see it spread. It must not be left to flourish.",starts={{npcID=161404,x=0.664,y=0.406,zoneID=9105}},ends={{npcID=161404,x=0.664,y=0.406,zoneID=9105}},coords={x=0.664,y=0.406,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Corruption Manifest"},
[58466] = {id=58466,name="Torment From Beyond",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="As if it were not bad enough that N'Zoth seeks to dominate those living in the Vale, my scouts report they now seek to dominate the dead! The Shado-Pan have their hands full defending the living. Can we rely on you to put an end to this disgrace?",starts={{npcID=161404,x=0.664,y=0.406,zoneID=9105}},ends={{npcID=161404,x=0.664,y=0.406,zoneID=9105}},coords={x=0.664,y=0.406,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Torment From Beyond"},
[58467] = {id=58467,name="Prisoners of Mind and Body",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="N'Zoth's forces struck the Vale suddenly. By the time I and my Shado-Pan arrived, many of the Golden Lotus had already been taken captive by the Old God's forces. Even with our combined might, we have only been able to hold off the invaders from taking more of our people. Those already taken, however, are still within the clutches of the Old God. I know we have had our differences, , but if you could aid us in their recovery, the Shado-Pan would be in your debt.",starts={{npcID=161404,x=0.664,y=0.406,zoneID=9105}},ends={{npcID=161404,x=0.664,y=0.406,zoneID=9105}},coords={x=0.664,y=0.406,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Prisoners of Mind and Body"},
[58468] = {id=58468,name="A Growing Darkness",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="Shado-Pan scouts have spotted evidence of a new mantid hatchery within the Big Blossom mine. It seems these Deephive mantid are looking to create new corrupted spawn to serve N'Zoth. If these eggs were allowed to hatch, a new swarm empowered by the Old God could blacken the skies of the Vale and plunge Pandaria into darkness. We will not allow that to happen, will we?",starts={{npcID=161405,x=0.372,y=0.792,zoneID=9105}},ends={{npcID=161405,x=0.372,y=0.792,zoneID=9105}},coords={x=0.372,y=0.792,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="A Growing Darkness"},
[58469] = {id=58469,name="Tears in the Vale",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=10833,mapID=1530,description="As N'Zoth's influence spreads within the Vale, our very reality begins to break down. The Old God's power has created tears in the fabric our world, acting as doorways for his minions to invade from his dark realm. As long as these tears exist, we will never be free from N'Zoth's grasp. Close them, and stem the tide of his corruption!",starts={{npcID=154261,x=0.838,y=0.49,zoneID=9105}},ends={{npcID=154261,x=0.838,y=0.49,zoneID=9105}},coords={x=0.838,y=0.49,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Tears in the Vale"},
[58470] = {id=58470,name="Corrupted Curiosities",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="I understand that the Black Empire poses a grave threat to Pandaria, but we may also use this as an opportunity! Though we've faced them several times before, very little is known about the Old Gods or N'Zoth's mysterious realm of Ny'alotha. When studying ancient civilizations, we often rely on artifacts to unlock the deepest mysteries lost to time. I wonder if some such artifacts could be found among the Old God's forces? It can't hurt to check, right?",starts={{npcID=156003,x=0.836,y=0.272,zoneID=9105}},ends={{npcID=156003,x=0.836,y=0.272,zoneID=9105}},coords={x=0.836,y=0.272,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Corrupted Curiosities"},
[58471] = {id=58471,name="Aggressive Notation",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="Even given the Sha's origins with the Old Gods, we in Pandaria still know very little of them. I would like to take this opportunity to add whatever information I can about them to the archives of the Lorewalkers. Of course, that becomes a bit problematic when they're trying to kill us. That doesn't seem to be a problem for you, though. Could you do me a favor and jot down some notes about what you encounter out there? It could help a great deal towards understanding what we're fighting.",starts={{npcID=156003,x=0.836,y=0.272,zoneID=9105}},ends={{npcID=156003,x=0.836,y=0.272,zoneID=9105}},coords={x=0.836,y=0.272,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Aggressive Notation"},
[58476] = {id=58476,name="Bringing the Thunder",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="All of the mogu clans are formidable, to be sure, but it is the Zan-Tien that pose the most direct threat to the Golden Lotus. Even now, their numbers are amassing outside the Golden Pagoda. Many of our warriors are fresh-faced and inexperienced. They would not withstand a mogu assault for long. An experienced like you could serve to slow them down significantly. Care to help?",starts={{npcID=158674,x=0.386,y=0.752,zoneID=9105}},ends={{npcID=158674,x=0.386,y=0.752,zoneID=9105}},coords={x=0.386,y=0.752,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Bringing the Thunder"},
[58477] = {id=58477,name="Through Blood and Dirt and Bone",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="The Dokani see themselves fit to wield the ancient magic of anima, but their golems and manifestations are but a fraction of anima's true power. Liberate them of their prized substance, so that the Rajani may put it to better use.",starts={{npcID=154444,x=0.446,y=0.74,zoneID=9105}},ends={{npcID=154444,x=0.446,y=0.74,zoneID=9105}},coords={x=0.446,y=0.74,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Through Blood and Dirt and Bone"},
[58478] = {id=58478,name="No Stone Unbroken",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="When the warring clans came into the Vale, the Baruk deigned themselves worthy to lay claim to the ancient grounds of Guo-Lai. They are not. Show these usurpers their place, and you may earn a modicum of favor with the Rajani.",starts={{npcID=154444,x=0.446,y=0.74,zoneID=9105}},ends={{npcID=154444,x=0.446,y=0.74,zoneID=9105}},coords={x=0.446,y=0.74,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="No Stone Unbroken"},
[58479] = {id=58479,name="Lightning Crashes",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="The Zan-Tien like to claim mastery over the power of storms, yet they resort to machines to harness lightning from the sky. Show these pretenders that the true power of storm and thunder comes from within. Break their toys, and see how they fare without.",starts={{npcID=154444,x=0.446,y=0.74,zoneID=9105}},ends={{npcID=154444,x=0.446,y=0.74,zoneID=9105}},coords={x=0.446,y=0.74,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Lightning Crashes"},
[58481] = {id=58481,name="Rituals of Blood",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="Anji and I have fought in many battles, so we know how to handle a few mogu, but the blood magic used by these Dokani is just unsettling! As if it weren't bad enough for them to kill everyone in their path, but to use their corpses to fuel their unholy rituals? I just can't stomach it! Do me a favor. If you ever come across any of these rituals, put a stop to them! Even our enemies don't deserve to be defiled with their dark magic.",starts={{npcID=158673,x=0.384,y=0.752,zoneID=9105}},ends={{npcID=158673,x=0.384,y=0.752,zoneID=9105}},coords={x=0.384,y=0.752,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Rituals of Blood"},
[58485] = {id=58485,name="Built to Fall",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="The Baruk use the forbidden arts of necromancy to trap souls of fallen mogu into the statues that fight for them. These tactics are a disgrace to our people, and cannot be allowed to continue. Break their precious statues, and give them no vessels with which to contaminate with their stolen spirits.",starts={{npcID=154444,x=0.446,y=0.74,mapID=1530}},ends={{npcID=154444,x=0.446,y=0.74,mapID=1530}},coords={x=0.446,y=0.74,source="quest_giver",mapID=1530},questType="world",worldTaskTitle="Built to Fall"},
[58487] = {id=58487,name="Plunder the Plunderers",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="Our raids on Lei Shen's treasuries did much to ensure the Thunder King's downfall. I think we should employ the same strategy here. Seek out the hoarded plunder of the mogu clans and relieve them of it. We must do all we can to disrupt their advance.",starts={{npcID=161405,x=0.372,y=0.792,zoneID=9105}},ends={{npcID=161405,x=0.372,y=0.792,zoneID=9105}},coords={x=0.372,y=0.792,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Plunder the Plunderers"},
[58595] = {id=58595,name="Pillars of Oblivion",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="In ages past, the black obelisks of the Old Gods would herald the coming of their forces. The dark conjurers among the k'thir and n'raqi would utilize these monuments to establish footholds in our world and usher in more of the Old Gods' minions. Today, we see these very same obelisks littering the battlefields. So long as they stand, N'Zoth's forces will be without end. Make sure they do not.",starts={{npcID=154444,x=0.446,y=0.74,zoneID=9105}},ends={{npcID=154444,x=0.446,y=0.74,zoneID=9105}},coords={x=0.446,y=0.74,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Pillars of Oblivion"},
[58660] = {id=58660,name="Burrowing Terrors",level=50,requiredLevel=50,faction="none",expansion=4,zoneID=10833,mapID=1530,questType="world",worldTaskTitle="Burrowing Terrors",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
