[58679] = {id=58679,name="Dormant Destroyer",expansion=4,mapID=1530,questType="world",worldTaskTitle="Dormant Destroyer",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[58705] = {id=58705,name="Grand Empress Shek'zara",level=50,requiredLevel=50,faction="none",expansion=4,zoneID=9105,mapID=1530,questType="world",worldTaskTitle="Grand Empress Shek'zara",db2QuestInfoID=112,db2QuestInfoName="Epic Elite World Quest"},
[58740] = {id=58740,name="Subjugated Serpents",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="Where the Zan-Tien march, the warserpents are sure to follow. I cannot stress to you enough how dangerous these beasts are. It is a shame to see them subjugated by the mogu, but we cannot afford to let them run rampant. I need you to put them down before they can wreak havoc on our lines.",starts={{npcID=158674,x=0.386,y=0.752,zoneID=9105}},ends={{npcID=158674,x=0.386,y=0.752,zoneID=9105}},coords={x=0.386,y=0.752,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Subjugated Serpents",db2QuestInfoID=1,db2QuestInfoName="Group"},
[58741] = {id=58741,name="Cutting Stone",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="One problem with waging war against other mogu is that weapons dull and break very quickly when used against foes of stone and metal. Being the sole blacksmith among the Rajani, it is sometimes difficult to keep up with our warriors needs. If you come across any weapons in your battles with the mogu, I'm sure I could put them to good use.",starts={{npcID=154677,x=0.438,y=0.718,zoneID=9105}},ends={{npcID=154677,x=0.438,y=0.718,zoneID=9105}},coords={x=0.438,y=0.718,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Cutting Stone"},
[58746] = {id=58746,name="Tiny Madness",expansion=4,mapID=1530,questType="world",db2Objectives={{orderIndex=0,type=12,amount=1,objectID=2858,text="Defeat K'tiny the Mad"}},worldTaskTitle="Tiny Madness",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
