[58749] = {id=58749,name="Flight of the Vil'thik",expansion=4,mapID=1530,questType="world",db2Objectives={{orderIndex=0,type=12,amount=1,objectID=2861,text="Defeat Vil'thik Hatchling"}},worldTaskTitle="Flight of the Vil'thik",db2QuestInfoID=115,db2QuestInfoName="Battle Pet World Quest"},
[58754] = {id=58754,name="Champions of the Swarm",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="It is clear that Shek'zara is fully committed to this invasion. Our scouts have spotted some of her greatest champions among the battlefield. Any one of these mantid could prove too much for the soldiers of the Golden Lotus to overcome. We must hunt them down and eliminate them ourselves. Are you in?",starts={{npcID=154444,x=0.446,y=0.74,zoneID=9105}},ends={{npcID=154444,x=0.446,y=0.74,zoneID=9105}},coords={x=0.446,y=0.74,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Champions of the Swarm"},
[58755] = {id=58755,name="Stashed Supplies",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="The invading mantid have been making off with the Golden Lotus' supplies lately. They're probably hoping they can starve us out. Well, they may be right if we can't get some of our supplies back. While you're taking the fight to the swarm, keep an eye out for anywhere they might have stashed our supplies. You'd be doing the Golden Lotus a big favor if you could recover some.",starts={{npcID=158673,x=0.384,y=0.752,zoneID=9105}},ends={{npcID=158673,x=0.384,y=0.752,zoneID=9105}},coords={x=0.384,y=0.752,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Stashed Supplies"},
[58756] = {id=58756,name="Dread Menders",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=5841,mapID=1530,description="The ambercasters are among the highest castes of mantid society. Through their magic, they can mend and form amber to their will, allowing hastened recovery of the mantid's forces after a battle. They are strategic targets, and we should seek them out. Care to join us?",starts={{npcID=161405,x=0.372,y=0.792,zoneID=9105}},ends={{npcID=161405,x=0.372,y=0.792,zoneID=9105}},coords={x=0.372,y=0.792,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Dread Menders"},
[58757] = {id=58757,name="Testing the Untested",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="During a swarm, the mantid send their youngest in great numbers against the enemy to test their mettle. Those who survive join the swarm as true warriors of the mantid. We should do our best to ensure that they don't make it through this test.",starts={{npcID=154444,x=0.446,y=0.74,mapID=1530}},ends={{npcID=154444,x=0.446,y=0.74,mapID=1530}},coords={x=0.446,y=0.74,source="quest_giver",mapID=1530},questType="world",worldTaskTitle="Testing the Untested"},
[58758] = {id=58758,name="Rampaging Destroyers",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="The last mantid swarm is still very fresh in the memory of the Golden Lotus. Prior to the advancement of the swarm, the mantid would send their massive kunchong to soften up the defenders' lines. It would seem their tactics have not changed. We must stop those kunchong if the Golden Lotus hope to mount a defensive against the swarm. I'm counting on you to strike them down.",starts={{npcID=158674,x=0.386,y=0.752,zoneID=9105}},ends={{npcID=158674,x=0.386,y=0.752,zoneID=9105}},coords={x=0.386,y=0.752,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Rampaging Destroyers",db2QuestInfoID=1,db2QuestInfoName="Group"},
[58759] = {id=58759,name="The Empress' Guard",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="The Zara'thik are the empress' elite guard. Empowered with plundered Azerite , they will stop at nothing short of absolute conquest of all of Pandaria. If we allow them to advance past the Serpent's spine, the Golden Lotus will be no match for them. Stop them at the wall, .",starts={{npcID=161405,x=0.372,y=0.792,zoneID=9105}},ends={{npcID=161405,x=0.372,y=0.792,zoneID=9105}},coords={x=0.372,y=0.792,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="The Empress' Guard",db2QuestInfoID=1,db2QuestInfoName="Group"},
[58760] = {id=58760,name="Blades of Amber",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="The mantid are frail and easily broken, but the amber blades they wield are formidable. With a bit of work, they could be reshaped into something suitable for the mogu. Bring them to me, and I can see about repurposing them to service the Rajani.",starts={{npcID=154677,x=0.438,y=0.718,zoneID=9105}},ends={{npcID=154677,x=0.438,y=0.718,zoneID=9105}},coords={x=0.438,y=0.718,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Blades of Amber"},
[58761] = {id=58761,name="Crushed Underfoot",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="In the past, the mantid would safeguard their hatchlings in incubation chambers until they were ready to be tested in the swarm. These Vil'thik are sloppy, however, allowing their larvae to scurry out in the open. Wouldn't it be a shame if someone crushed them? No, of course it wouldn't.",starts={{npcID=154444,x=0.446,y=0.74,zoneID=9105}},ends={{npcID=154444,x=0.446,y=0.74,zoneID=9105}},coords={x=0.446,y=0.74,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Crushed Underfoot"},
[58762] = {id=58762,name="Taken by the Swarm",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="There's something different about this mantid swarm. Instead of just killing everything in sight like the mantid usually do, they've taken to capturing our defenders and holding them alive. I really don't want to know what they have in store for the captives. Why don't you go rescue them so we don't have to find out?",starts={{npcID=158673,x=0.384,y=0.752,zoneID=9105}},ends={{npcID=158673,x=0.384,y=0.752,zoneID=9105}},coords={x=0.384,y=0.752,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Taken by the Swarm"},
[58763] = {id=58763,name="Halting Production",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="The mantid use amber in nearly all aspects of their lives, from the structures they live in to the weapons they wield. Of course, I'm more interested in the latter. If we can deprive the mantid of their materials, we will deprive them of their means to create implements of war. Find where they keep their amber and make sure they are unable to use it.",starts={{npcID=161405,x=0.372,y=0.792,zoneID=9105}},ends={{npcID=161405,x=0.372,y=0.792,zoneID=9105}},coords={x=0.372,y=0.792,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Halting Production"},
[58764] = {id=58764,name="Standards of the Swarm",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="The brazen mantid think they've already won. Even now, they fly banners along the Serpent's Spine, announcing their dominance. They must learn that Pandaria belongs to the pandaren. Burn their banners down.",starts={{npcID=158674,x=0.386,y=0.752,zoneID=9105}},ends={{npcID=158674,x=0.386,y=0.752,zoneID=9105}},coords={x=0.386,y=0.752,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Standards of the Swarm"},
[58765] = {id=58765,name="Siege Breaker",level=50,requiredLevel=50,faction="both",expansion=4,zoneID=9105,mapID=1530,description="The Golden Lotus can hold their own against the mantid's warriors, of that I have no doubt. Their war wagons, on the other hand, have the capability of crippling an entire squad of our fighters in a single volley. If we wish to maintain the upper hand in this battle, we will need someone to infiltrate their positions and sabotage their siege engines. I would like you to volunteer.",starts={{npcID=158674,x=0.386,y=0.752,zoneID=9105}},ends={{npcID=158674,x=0.386,y=0.752,zoneID=9105}},coords={x=0.386,y=0.752,source="quest_giver",zoneID=9105},questType="world",worldTaskTitle="Siege Breaker"},
